:root {
  --ink: #202b3a;
  --paper: #ffffff;
  --line: #cdd8e6;
  --soft: #edf4fb;
  --accent: #1668d8;
  --accent-ink: #ffffff;
  --ready-bg: #dff5e8;
  --ready-ink: #167247;
}

.merge-note {
  width: 440px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: var(--paper);
}

.merge-note header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 14px;
  border-bottom: 1px solid var(--line);
  background: var(--soft);
}

.merge-note h2 {
  margin: 0;
  color: var(--ink);
  font-size: 18px;
  line-height: 1;
}

.status {
  padding: 4px 7px;
  border-radius: 999px;
  background: var(--ready-bg);
  color: var(--ready-ink);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.7px;
}

.merge-note p {
  margin: 0;
  padding: 14px;
  color: var(--ink);
  font-size: 14px;
  line-height: 1.4;
}

.merge-note footer {
  padding: 0 14px 14px;
}

.merge-note button {
  border: 0;
  border-radius: 8px;
  padding: 8px 11px;
  background: var(--accent);
  color: var(--accent-ink);
  font-size: 13px;
  font-weight: 700;
}
